import { cacheTag } from 'next/cache'
import { getAllProducts } from './db.js'

export type Product = {
  id: number
  name: string
  price: number
  inventory: number
  available: boolean
}

export async function getProducts(): Promise<Product[]> {
  'use cache'
  cacheTag('products')
  const products = await getAllProducts()
  return products.map((p) => ({
    ...p,
    inventory: 100,
    available: true,
  }))
}
